### C++

```cpp
#include <iostream>
#include <vector>
using namespace std;

vector<int> solve(int n, const vector<int>& A, const vector<int>& B) {
    // 记录每个数字在 A 和 B 中的位置（下标从 1 开始）
    vector<int> posA(n + 1), posB(n + 1);

    for (int i = 0; i < n; i++) {
        posA[A[i]] = i + 1;
        posB[B[i]] = i + 1;
    }

    vector<int> ans;
    int i = 1, j = 1; // 当前在 A 和 B 中允许选择的最小位置

    // 从大到小扫描，贪心选择当前还能选的最大数字
    for (int x = n; x >= 1; x--) {
        if (posA[x] >= i && posB[x] >= j) {
            ans.push_back(x);
            // 更新后续可选位置
            i = posA[x] + 1;
            j = posB[x] + 1;
        }
    }

    return ans;
}

int main() {
    int n;
    cin >> n;

    vector<int> A(n), B(n);
    for (int i = 0; i < n; i++) cin >> A[i];
    for (int i = 0; i < n; i++) cin >> B[i];

    vector<int> ans = solve(n, A, B);

    cout << ans.size() << "\n";
    for (int i = 0; i < (int)ans.size(); i++) {
        if (i) cout << " ";
        cout << ans[i];
    }
    cout << "\n";

    return 0;
}
